package main

import (
	"gno.land/r/gov/dao"
	impl "gno.land/r/gov/dao/impl/v0"
)

func main(cur realm) {
	req := impl.NewAddMemberRequest(cross(cur), "g1m0rgan0rla00ygmdmp55f5m0unvsvknluyg2a4", "T1", "Core gno engineer. Author of Dora, the automated security and pull request scanner, and of the replay tool that checks per pull request that a replay does not break consensus. GitHub thehowl.")
	println("proposal id:", dao.MustCreateProposal(cross(cur), req))
}

